import React, { useState, useEffect } from 'react'
import Typography from '@mui/material/Typography';
import Paper from '@mui/material/Paper';
import TextField from '@mui/material/TextField';
import Button from '@mui/material/Button';
import axios from 'axios';
import { useParams } from 'react-router-dom';

export default function UpdateUser() {

  const { id } = useParams();

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    phone: '',
    address: ''
  })

  useEffect(() => {
    axios.get(`http://localhost:7000/user/getUserById/${id}`)
      .then((res) => {
        setFormData(res.data.data);
      })
      .catch((error) => {
        console.log(error);
      });
  }, [id]);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    })
  }

  const handleUpdate = async () => {
    try {
      const updateData = {
        name: formData.name,
        email: formData.email,
        password: formData.password,
        phone: formData.phone,
        address: formData.address
      };

      const res = await axios.put(
        `http://localhost:7000/user/updateUser/${id}`,
        updateData
      );

      console.log(res.data);
      alert("User Updated Successfully");

    } catch (error) {
      console.log(error);
      alert("Error Updating User");
    }
  }

  return (
    <div>
      <Paper elevation={20} style={{ width: "590px", padding: "30px" }}>
        <Typography variant='h4' style={{ textAlign: "center", fontFamily: "Times new roman" }}>Update User</Typography>

        <TextField
          variant='filled'
          type='text'
          label="Name"
          name='name'
          value={formData.name}
          fullWidth
          style={{ marginBottom: "20px", marginLeft: "5px" }}
          onChange={handleChange}
        />

        <TextField
          variant='filled'
          type='email'
          label="Email"
          name='email'
          value={formData.email}
          fullWidth
          style={{ marginBottom: "20px" }}
          onChange={handleChange}
        />

        <TextField
          variant='outlined'
          type='password'
          label="Password"
          name='password'
          value={formData.password}
          fullWidth
          style={{ marginBottom: "20px" }}
          onChange={handleChange}
        />

        <TextField
          variant='standard'
          type='tel'
          label="Phone"
          name='phone'
          value={formData.phone}
          fullWidth
          style={{ marginBottom: "20px" }}
          onChange={handleChange}
        />

        <TextField
          variant='filled'
          multiline
          rows={5}
          type='text'
          label="Address"
          name='address'
          value={formData.address}
          fullWidth
          style={{ marginBottom: "20px" }}
          onChange={handleChange}
        />

        <Button variant='contained' fullWidth onClick={handleUpdate}>
          Update User
        </Button>

      </Paper>
    </div>
  )
}